function rule(id, config) {
  return Object.freeze({
    id,
    priority: 50,
    aliases: [],
    terms: [],
    requires: [],
    excludes: [],
    collectionTargets: [],
    // A product keeps one primary taxonomy path. Valid cross-department or
    // cross-category discovery is expressed with additive controlled tags.
    relatedCategories: [],
    ...config,
  });
}

