function asText(value) {
  if (Array.isArray(value)) return value.filter(Boolean).join(" ");
  return value == null ? "" : String(value);
}

export function normalizeCatalogText(value) {
  return asText(value)
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/<[^>]+>/g, " ")
    .replace(/[^a-z0-9]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

export function singularizeCatalogToken(token) {
  if (token.endsWith("ies") && token.length > 4) return `${token.slice(0, -3)}y`;
  if (token.endsWith("ses") && token.length > 5) return token.slice(0, -2);
  if (token.endsWith("s") && token.length > 3 && !token.endsWith("ss")) return token.slice(0, -1);
  return token;
}

export function tokenizeCatalogText(value) {
  return normalizeCatalogText(value)
    .split(" ")
    // Keep the meaningful one-character tokens used by taxonomy phrases such
    // as "O-ring" and "Type-C". Dropping them turns those phrases into broad
    // single-word matches and creates false positives.
    .filter((token) => token.length > 1 || /\d/.test(token) || token === "o" || token === "c");
}

const COMPILED_ATTRIBUTE_GROUPS = Object.freeze(
  Object.fromEntries(
    Object.entries(ATTRIBUTE_GROUPS).map(([group, values]) => [
      group,
      values.map((value) => ({ value, tokens: tokenizeCatalogText(value) })),
    ]),
  ),
);

const ATTRIBUTE_TRIGGER_TOKENS = new Set(
  Object.values(COMPILED_ATTRIBUTE_GROUPS)
    .flat()
    .flatMap((entry) => entry.tokens),
);

function unique(values) {
  return Array.from(new Set(values.filter(Boolean)));
}

function pluralAwareEquals(left, right) {
  return left === right || singularizeCatalogToken(left) === singularizeCatalogToken(right);
}

function phraseTokens(value) {
  return tokenizeCatalogText(value);
}

function includesPhrase(tokens, phrase) {
  const phraseTokenList = Array.isArray(phrase) ? phrase : phraseTokens(phrase);
  if (!phraseTokenList.length || phraseTokenList.length > tokens.length) return false;

  for (let offset = 0; offset <= tokens.length - phraseTokenList.length; offset += 1) {
    let matches = true;
    for (let index = 0; index < phraseTokenList.length; index += 1) {
      if (!pluralAwareEquals(tokens[offset + index], phraseTokenList[index])) {
        matches = false;
        break;
      }
    }
    if (matches) return true;
  }
  return false;
}

function unmanagedTagText(tags) {
  const values = Array.isArray(tags) ? tags : String(tags || "").split(",");
  return values
    .map((tag) => String(tag || "").trim())
    .filter((tag) => tag && !/^salt:/i.test(tag))
    .join(" ");
}

function buildEvidence(product) {
  const tags = unmanagedTagText(product?.tags);
  const customData = product?.customData || {};
  const fields = {
    title: tokenizeCatalogText(product?.title),
    handle: tokenizeCatalogText(product?.handle),
    productType: tokenizeCatalogText(product?.product_type || product?.productType),
    tags: tokenizeCatalogText(tags),
    collectionSignal: tokenizeCatalogText(customData.collectionSignal),
  };

  // Collection signals are generated merchandising metadata and can lag a
  // product correction. Never let that derived field override direct product
  // language or controlled tags; use it only when the catalog record has no
  // direct evidence at all.
  if (["title", "handle", "productType", "tags"].some((field) => fields[field].length)) {
    fields.collectionSignal = [];
  }

  const allTokens = unique(Object.values(fields).flat());
  const tokenSet = new Set([...allTokens, ...allTokens.map(singularizeCatalogToken)]);
  return { fields, allTokens, tokenSet };
}

function hasPhraseInEvidence(evidence, phrase) {
  const matches = [];
  for (const [field, tokens] of Object.entries(evidence.fields)) {
    if (includesPhrase(tokens, phrase)) matches.push(field);
  }
  return matches;
}

function normalizeTerms(terms) {
  return unique((Array.isArray(terms) ? terms : []).map(normalizeCatalogText).filter(Boolean));
}

function ruleSearchTerms(entry) {
  return unique([
    ...normalizeTerms(entry.terms),
    ...entry.requires.flatMap((group) => normalizeTerms(group)),
  ]);
}

const RULES_BY_TOKEN = (() => {
  const index = new Map();
  const nonDiscriminatingTokens = new Set(["type", "product", "accessory", "accessories"]);
  for (const entry of TAXONOMY_RULES) {
    for (const term of ruleSearchTerms(entry)) {
      for (const token of phraseTokens(term)) {
        if (nonDiscriminatingTokens.has(token)) continue;
        const keys = [token, singularizeCatalogToken(token)];
        for (const key of keys) {
          if (!index.has(key)) index.set(key, new Set());
          index.get(key).add(entry);
        }
      }
    }
  }
  return index;
})();

function candidateRules(evidence) {
  const candidates = new Set();
  for (const token of evidence.tokenSet) {
    RULES_BY_TOKEN.get(token)?.forEach((entry) => candidates.add(entry));
  }
  return [...candidates];
}

function fieldWeight(field) {
  if (field === "title") return 34;
  if (field === "handle") return 30;
  if (field === "productType") return 22;
  if (field === "tags") return 8;
  return 5;
}

function canonicalMatchKey(term) {
  return phraseTokens(term).map(singularizeCatalogToken).join(" ");
}

function consolidateMatches(matches) {
  const consolidated = new Map();
  for (const match of matches) {
    const key = canonicalMatchKey(match.term);
    const current = consolidated.get(key);
    if (!current) {
      consolidated.set(key, { term: match.term, fields: [...match.fields] });
      continue;
    }
    current.fields = unique([...current.fields, ...match.fields]);
  }
  return [...consolidated.values()];
}

function directEvidenceRank(fields) {
  if (fields.has("title")) return 3;
  if (fields.has("handle")) return 2;
  if (fields.has("productType")) return 1;
  return 0;
}

const CONNECTOR_GENDER_CONTEXT = /\b(?:cable|connector|terminal|plug|jack|socket|port|pin|thread(?:ed|s)?|adapter|audio|camera|tripod|mount|bracket|arm|screw|bolt|wire|xh2|usb|aux|hot\s+shoe)\b/i;

function isConnectorGenderTerm(fieldTokens, audience, term) {
  if (!["men", "women"].includes(audience) || !["male", "female"].includes(term.term)) {
    return false;
  }
  return CONNECTOR_GENDER_CONTEXT.test(fieldTokens.join(" "));
}

function directAudienceIds(evidence) {
  const directTokens = ["title", "handle", "productType"].flatMap((field) => evidence.fields[field] || []);
  const audienceIds = new Set();

  for (const [audience, terms] of Object.entries(COMPILED_AUDIENCE_TERMS)) {
    if (terms.some((term) => includesPhrase(directTokens, term.tokens) && !isConnectorGenderTerm(directTokens, audience, term))) {
      audienceIds.add(audience === "baby" ? "kids" : audience);
    }
  }

  return audienceIds;
}

function explicitRuleAudience(entry) {
  const override = normalizeCatalogText(entry?.audienceOverride);
  if (Object.prototype.hasOwnProperty.call(AUDIENCE_TERMS, override)) {
    return override === "baby" ? "kids" : override;
  }

  const departmentId = normalizeCatalogText(entry?.departmentId);
  if (["women", "men", "kids"].includes(departmentId)) return departmentId;

  const categoryId = normalizeCatalogText(entry?.categoryId);
  if (/^(women|men|kids)-/.test(categoryId)) return categoryId.split("-", 1)[0];
  return null;
}

function scoreRule(entry, evidence) {
  const expectedAudience = explicitRuleAudience(entry);
  if (expectedAudience) {
    const directAudiences = directAudienceIds(evidence);
    const hasExpectedAudience = directAudiences.has(expectedAudience);
    const hasConflictingAudience = [...directAudiences]
      .filter((audience) => ["women", "men", "kids"].includes(audience))
      .some((audience) => audience !== expectedAudience);
    // A stale supplier tag may satisfy an audience-specific rule, but it must
    // not override a direct audience phrase in the title or handle.
    if (!hasExpectedAudience && hasConflictingAudience) return null;
  }

  const excluded = normalizeTerms(entry.excludes).find((term) => hasPhraseInEvidence(evidence, term).length);
  if (excluded) return null;

  const requiredMatches = [];
  for (const group of entry.requires) {
    const groupHits = normalizeTerms(group)
      .map((term) => ({ term, fields: hasPhraseInEvidence(evidence, term) }))
      .filter((match) => match.fields.length);
    if (!groupHits.length) return null;
    requiredMatches.push(...groupHits);
  }

  if (entry.primaryTerms?.length) {
    const primaryFields = ["title", "handle"];
    const hasPrimaryTerm = normalizeTerms(entry.primaryTerms).some((term) =>
      primaryFields.some((field) => includesPhrase(evidence.fields[field], term)),
    );
    if (!hasPrimaryTerm) return null;
  }

  const termMatches = normalizeTerms(entry.terms)
    .map((term) => ({ term, fields: hasPhraseInEvidence(evidence, term) }))
    .filter((match) => match.fields.length);
  if (entry.terms.length && !termMatches.length && !requiredMatches.length) return null;

  // Singular/plural spellings are one piece of evidence. Counting a supplier
  // tag such as "wallets" twice must not beat a clear "bag" title.
  const matches = consolidateMatches([...termMatches, ...requiredMatches]);
  const fields = new Set(matches.flatMap((match) => match.fields));
  const matchScore = matches.reduce((total, match) => {
    const lengthBonus = Math.min(3, phraseTokens(match.term).length);
    return total + Math.max(...match.fields.map((field) => fieldWeight(field) * lengthBonus));
  }, 0);
  const directFields = ["title", "handle", "productType"].filter((field) => fields.has(field));
  const directPhraseMatches = matches.filter((match) =>
    phraseTokens(match.term).length >= 2 && match.fields.some((field) => directFields.includes(field)),
  );
  const requiredGroupCount = entry.requires.filter((group) => normalizeTerms(group).some((term) => hasPhraseInEvidence(evidence, term).length)).length;
  const evidenceLanes = unique([
    directFields.length ? "direct-text" : "",
    directPhraseMatches.length ? "phrase-anchor" : "",
    requiredGroupCount >= 2 ? "required-groups" : "",
    fields.has("tags") ? "supplier-metadata" : "",
    fields.has("collectionSignal") ? "collection-signal" : "",
  ]);
  const titleOrHandle = fields.has("title") || fields.has("handle");
  const primaryEvidence = titleOrHandle || fields.has("productType");
  // Priority resolves true taxonomy conflicts, while field evidence resolves
  // supplier-language noise. A title noun such as "hat" must beat an incidental
  // handle descriptor such as "sunscreen" rather than being trapped by a
  // broad high-priority skincare rule.
  const score = entry.priority * 3 + matchScore + requiredMatches.length * 24;
  // Keep the legacy priority score, but rank candidates with independent
  // evidence lanes as well. This prevents one incidental noun from beating a
  // product noun supported by a phrase anchor and a second direct field.
  const consensusScore = score +
    directPhraseMatches.length * 10 +
    Math.max(0, directFields.length - 1) * 5 +
    (requiredGroupCount >= 2 ? 8 : 0) +
    // Independent direct fields are stronger than repeated supplier metadata.
    // This bonus lets a title + handle/product-type consensus beat a single
    // incidental high-frequency token without making tags authoritative.
    (directFields.length >= 2 || requiredGroupCount >= 2 || directPhraseMatches.length >= 2 ? 12 : 0);

  return {
    entry,
    score,
    consensusScore,
    fields: [...fields],
    terms: unique(matches.map((match) => match.term)),
    evidenceLanes,
    directFields,
    directPhraseCount: directPhraseMatches.length,
    requiredGroupCount,
    independentEvidence: directFields.length >= 2 || requiredGroupCount >= 2 || directPhraseMatches.length >= 2,
    titleOrHandle,
    primaryEvidence,
    directEvidenceRank: directEvidenceRank(fields),
  };
}

function inferAudience(evidence) {
  // Supplier tags and descriptions are not authoritative audience evidence.
  // They frequently contain stale merchandising labels (for example `women`
  // on a camera accessory). Connector terminology is also not a shopper
  // audience: `male-to-male` and `female terminal` describe the hardware.
  const directFields = ["title", "handle", "productType"];
  const allDirectTokens = directFields.flatMap((field) => evidence.fields[field] || []);
  const directText = allDirectTokens.join(" ");
  // PET is also a common solar-panel material (ETFE/PET), not a pet-owner
  // audience signal. Keep the audience neutral when the material appears in
  // an explicit flexible-solar-panel context.
  const petMaterialContext = /\b(?:etfe\s+pet|pet\s+etfe)\b.{0,48}\bsolar\s+panel(?:s)?\b|\bsolar\s+panel(?:s)?\b.{0,48}\b(?:etfe\s+pet|pet\s+etfe)\b/i.test(directText);
  const signals = new Map();
  for (const [audience, terms] of Object.entries(COMPILED_AUDIENCE_TERMS)) {
    let score = 0;
    for (const term of terms) {
      for (const field of directFields) {
        const fieldTokens = evidence.fields[field] || [];
        if (!includesPhrase(fieldTokens, term.tokens) || isConnectorGenderTerm(allDirectTokens, audience, term)) {
          continue;
        }
        if (audience === "pets" && term.term === "pet" && petMaterialContext) continue;
        score += field === "title" ? 5 : field === "handle" ? 4 : 3;
      }
    }
    if (score) signals.set(audience, score);
  }

  const ranked = [...signals.entries()].sort((left, right) => right[1] - left[1] || left[0].localeCompare(right[0]));
  if (!ranked.length) return { id: "unisex", label: "Unisex", confidence: 0, signals: [] };
  const [id, score] = ranked[0];
  return {
    id,
    label: id === "kids" ? "Kids" : id === "baby" ? "Baby" : id === "pets" ? "Pets" : id[0].toUpperCase() + id.slice(1),
    confidence: score,
    signals: ranked.map(([key]) => key),
  };
}

function applyRuleAudienceOverride(entry, audience) {
  const override = normalizeCatalogText(entry?.audienceOverride);
  if (!Object.prototype.hasOwnProperty.call(AUDIENCE_TERMS, override)) {
    return audience;
  }

  const label = override === "kids" ? "Kids" : override === "baby" ? "Baby" : override === "pets" ? "Pets" : override[0].toUpperCase() + override.slice(1);
  return {
    ...audience,
    id: override,
    label,
    confidence: Math.max(Number(audience?.confidence) || 0, 100),
    signals: unique([override, ...(Array.isArray(audience?.signals) ? audience.signals : [])]),
    source: "taxonomy-rule",
  };
}

function audiencePrefix(audience) {
  if (audience.id === "women") return { id: "women", label: "Women" };
  if (audience.id === "men") return { id: "men", label: "Men" };
  if (audience.id === "kids" || audience.id === "baby") return { id: "kids", label: "Kids" };
  return { id: "general", label: "Fashion" };
}

function resolveAudienceTaxonomy(entry, audience) {
  if (!entry.audienceCategory) {
    return {
      departmentId: entry.departmentId,
      departmentLabel: DEPARTMENTS[entry.departmentId] || entry.departmentId,
      categoryId: entry.categoryId,
      categoryLabel: entry.categoryLabel,
    };
  }

  const prefix = audiencePrefix(audience);
  if (entry.audienceCategory === "fashion") {
    if (prefix.id === "kids") {
      return { departmentId: "kids", departmentLabel: DEPARTMENTS.kids, categoryId: "kids-wear", categoryLabel: "Kids Wear" };
    }
    if (prefix.id === "women" || prefix.id === "men") {
      return {
        departmentId: prefix.id,
        departmentLabel: prefix.label,
        categoryId: `${prefix.id}-fashion`,
        categoryLabel: `${prefix.label}'s Fashion`,
      };
    }
    return { departmentId: "general", departmentLabel: "Fashion", categoryId: "fashion", categoryLabel: "Fashion" };
  }

  if (entry.audienceCategory === "accessories") {
    if (prefix.id === "women" || prefix.id === "men") {
      return {
        departmentId: prefix.id,
        departmentLabel: prefix.label,
        categoryId: `${prefix.id}-accessories`,
        categoryLabel: `${prefix.label}'s Accessories`,
      };
    }
    if (prefix.id === "kids") {
      return { departmentId: "kids", departmentLabel: DEPARTMENTS.kids, categoryId: "kids-accessories", categoryLabel: "Kids Accessories" };
    }
    return { departmentId: "general", departmentLabel: "Fashion", categoryId: "fashion-accessories", categoryLabel: "Fashion Accessories" };
  }

  if (entry.audienceCategory === "bags") {
    if (prefix.id === "women" || prefix.id === "men") {
      return {
        departmentId: prefix.id,
        departmentLabel: prefix.label,
        categoryId: `${prefix.id}-bags-wallets`,
        categoryLabel: `${prefix.label}'s Bags & Wallets`,
      };
    }
    return { departmentId: "general", departmentLabel: "Fashion", categoryId: "bags-wallets", categoryLabel: "Bags & Wallets" };
  }

  if (entry.audienceCategory === "beauty") {
    if (prefix.id === "women" || prefix.id === "men") {
      return {
        departmentId: prefix.id,
        departmentLabel: prefix.label,
        categoryId: `${prefix.id}-beauty-skincare`,
        categoryLabel: `${prefix.label}'s Beauty & Skincare`,
      };
    }
    return { departmentId: "general", departmentLabel: "Beauty", categoryId: "beauty-skincare", categoryLabel: "Beauty & Skincare" };
  }

  return {
    departmentId: entry.departmentId || "general",
    departmentLabel: DEPARTMENTS[entry.departmentId] || "General Merchandise",
    categoryId: entry.categoryId || "general",
    categoryLabel: entry.categoryLabel || "General Merchandise",
  };
}

function resolveCollectionTargets(entry, audience) {
  return unique(entry.collectionTargets.filter((target) => {
    if (LEGACY_COLLECTION_TARGETS_REQUIRING_REBUILD.has(target)) return false;
    if (target === "women-bags-and-wallets" || target === "womens-beauty-essentials") {
      return audience.id === "women";
    }
    if (target === "men-collection") return audience.id === "men";
    return true;
  }));
}

function normalizeTaxonomyId(value) {
  return normalizeCatalogText(value).replace(/\s+/g, "-");
}

function resolveRelatedCategories(entry, primaryTaxonomy) {
  const primaryKey = `${primaryTaxonomy.departmentId}:${primaryTaxonomy.categoryId}`;
  const seen = new Set([primaryKey]);
  const related = [];

  for (const definition of entry.relatedCategories || []) {
    const departmentId = normalizeTaxonomyId(definition?.departmentId);
    const categoryId = normalizeTaxonomyId(definition?.categoryId);
    if (!departmentId || !categoryId) {
      throw new Error(`Taxonomy rule ${entry.id} has an invalid related category definition.`);
    }

    const key = `${departmentId}:${categoryId}`;
    if (seen.has(key)) continue;
    seen.add(key);
    related.push({
      departmentId,
      departmentLabel: definition.departmentLabel || DEPARTMENTS[departmentId] || departmentId,
      categoryId,
      categoryLabel: definition.categoryLabel || categoryId,
      subcategoryId: normalizeTaxonomyId(definition.subcategoryId),
      subcategoryLabel: definition.subcategoryLabel || "",
      relationship: normalizeCatalogText(definition.relationship) || "related-product-use",
    });
  }

  return related;
}

export function extractCatalogAttributes(product, existingEvidence = null) {
  const evidence = existingEvidence || buildEvidence(product);
  const textTokens = evidence.allTokens;
  const directTokens = unique([
    ...evidence.fields.title,
    ...evidence.fields.handle,
    ...evidence.fields.productType,
  ]);
  const attributes = {};

  const hasAttributeSignal = textTokens.some((token) => ATTRIBUTE_TRIGGER_TOKENS.has(token) || ATTRIBUTE_TRIGGER_TOKENS.has(singularizeCatalogToken(token)));

  // Connectivity is frequently polluted by supplier tags. Require direct
  // product language for these attributes so a tag such as "wireless" cannot
  // turn an explicitly wired mouse or keyboard into a wireless product.
  const hasDirectWireless = ["wireless", "cordless", "2.4g", "2.4 ghz", "wifi", "wi fi", "dual mode"]
    .some((term) => includesPhrase(directTokens, phraseTokens(term)));
  const hasDirectBluetooth = includesPhrase(directTokens, phraseTokens("bluetooth"));
  const hasDirectWiredDevice = includesPhrase(directTokens, phraseTokens("wired")) && [
    "mouse", "keyboard", "headset", "headphone", "earphone", "earbud", "controller", "gamepad", "microphone",
  ].some((term) => includesPhrase(directTokens, phraseTokens(term)));

  if (hasAttributeSignal) {
    for (const [group, values] of Object.entries(COMPILED_ATTRIBUTE_GROUPS)) {
      const matches = values
        .filter((entry) => {
          if (entry.value === "wireless") return hasDirectWireless && !hasDirectWiredDevice;
          if (entry.value === "bluetooth") return hasDirectBluetooth && !hasDirectWiredDevice;
          return true;
        })
        .filter((entry) => includesPhrase(textTokens, entry.tokens))
        .map((entry) => entry.value);
      if (matches.length) attributes[group] = unique(matches).slice(0, 8);
    }
  }

  const measuredText = [
    product?.title,
    product?.handle,
    product?.product_type || product?.productType,
    unmanagedTagText(product?.tags),
  ].filter(Boolean).join(" ").toLowerCase();
  const measurements = /\d/.test(measuredText)
    ? measuredText.match(/\b\d+(?:\.\d+)?\s?(?:ml|l|mg|g|kg|mm|cm|m|inch|in|ft|v|w|mah|gb|tb|pcs?|pieces?|pack|pairs?)\b/g) || []
    : [];
  if (measurements.length) attributes.measurements = unique(measurements).slice(0, 8);

  return attributes;
}

function buildTaxonomyTags(classification) {
  const tags = [
    simpleCatalogTag("department", classification.departmentId),
    simpleCatalogTag("category", classification.categoryId),
    simpleCatalogTag("type", classification.canonicalTypeId),
  ];
  for (const related of classification.relatedCategories || []) {
    tags.push(simpleCatalogTag("department", related.departmentId));
    tags.push(simpleCatalogTag("category", related.categoryId));
  }
  if (["women", "men", "kids", "baby", "pets"].includes(classification.audience.id)) {
    tags.push(simpleCatalogTag("audience", classification.audience.id));
  }
  for (const feature of classification.attributes.features || []) {
    if (["wireless", "rechargeable", "portable", "waterproof", "foldable", "adjustable", "led", "smart", "bluetooth", "insulated"].includes(feature)) {
      tags.push(simpleCatalogTag("feature", feature));
    }
  }
  for (const compatibility of classification.attributes.compatibility || []) {
    if (["iphone", "android", "airpods", "ipad", "laptop", "macbook", "samsung", "usb c", "type c"].includes(compatibility)) {
      tags.push(simpleCatalogTag("compatibility", compatibility));
    }
  }
  return unique(tags).slice(0, 10);
}

function toTypeId(value) {
  return normalizeCatalogText(value).replace(/\s+/g, "-") || "unclassified-product";
}

function fallbackClassification(product, audience, attributes) {
  const explicitType = normalizeCatalogText(product?.product_type || product?.productType);
  const titleTokens = tokenizeCatalogText(product?.title).filter((token) => !GENERIC_TOKENS.has(token));
  const canonicalType = explicitType || titleTokens.slice(0, 5).join(" ") || "Unclassified Product";
  const classification = {
    version: CATALOG_TAXONOMY_VERSION,
    ruleId: "unclassified",
    familyId: "other",
    familyLabel: FAMILY_LABELS.other,
    departmentId: "general",
    departmentLabel: DEPARTMENTS.general,
    categoryId: "unclassified",
    categoryLabel: "Unclassified - Review Required",
    subcategoryId: "unclassified",
    subcategoryLabel: "Unclassified",
    canonicalType,
    canonicalTypeId: toTypeId(canonicalType),
    audience,
    attributes,
    relatedCategories: [],
    aliases: unique([canonicalType, ...titleTokens.slice(0, 6)]),
    negativeTerms: [],
    collectionTargets: [],
    shopifyCategory: null,
    confidence: 20,
    reviewRequired: true,
    reviewReasons: ["no-taxonomy-rule"],
    evidence: { fields: [], terms: [] },
  };
  // An unknown product is a review task, never a managed SEO tag.
  classification.seoEligible = false;
  classification.proposedTags = [];
  return classification;
}

function classificationFromApprovedOverride(override, evidence, audience, attributes) {
  const entry = TAXONOMY_RULES.find((candidate) => candidate.id === override.ruleId);
  if (!entry) {
    throw new Error(`Catalog taxonomy override ${override.id || "unknown"} references missing rule ${override.ruleId}.`);
  }

  const resolvedAudience = applyRuleAudienceOverride(entry, audience);
  const taxonomy = resolveAudienceTaxonomy(entry, resolvedAudience);
  const classification = {
    version: CATALOG_TAXONOMY_VERSION,
    ruleId: entry.id,
    familyId: entry.familyId,
    familyLabel: FAMILY_LABELS[entry.familyId] || FAMILY_LABELS.other,
    departmentId: taxonomy.departmentId,
    departmentLabel: taxonomy.departmentLabel,
    categoryId: taxonomy.categoryId,
    categoryLabel: taxonomy.categoryLabel,
    subcategoryId: entry.subcategoryId,
    subcategoryLabel: entry.subcategoryLabel,
    canonicalType: entry.canonicalType,
    canonicalTypeId: toTypeId(entry.canonicalType),
    audience: resolvedAudience,
    attributes,
    relatedCategories: resolveRelatedCategories(entry, taxonomy),
    aliases: unique([entry.canonicalType, ...entry.aliases]).slice(0, 24),
    negativeTerms: normalizeTerms(entry.excludes).slice(0, 16),
    collectionTargets: resolveCollectionTargets(entry, resolvedAudience),
    shopifyCategory: entry.shopifyCategory || null,
    confidence: 99,
    reviewRequired: false,
    reviewReasons: [],
    seoEligible: entry.seoEligible !== false,
    override: {
      id: override.id || "approved-override",
      reason: override.reason || "Approved product-level correction.",
    },
    evidence: { fields: ["approved-override"], terms: [entry.canonicalType] },
  };
  classification.proposedTags = classification.seoEligible ? buildTaxonomyTags(classification) : [];
  return classification;
}

export function classifyCatalogTaxonomyByRuleId(product, ruleId, {
  source = "release-override",
  reason = "Release-time evidence selected an existing taxonomy rule.",
} = {}) {
  const normalizedRuleId = normalizeTaxonomyId(ruleId);
  if (!normalizedRuleId) throw new Error("A taxonomy rule id is required for a release override.");
  const evidence = buildEvidence(product);
  const audience = inferAudience(evidence);
  const attributes = extractCatalogAttributes(product, evidence);
  return classificationFromApprovedOverride({
    id: `${source}:${normalizedRuleId}`,
    ruleId: normalizedRuleId,
    approved: true,
    reason,
  }, evidence, audience, attributes);
}

export function classifyCatalogTaxonomy(product, { ignoreOverride = false } = {}) {
  const evidence = buildEvidence(product);
  const audience = inferAudience(evidence);
  const attributes = extractCatalogAttributes(product, evidence);
  const override = ignoreOverride ? null : getCatalogTaxonomyOverride(product);
  if (override) return classificationFromApprovedOverride(override, evidence, audience, attributes);
  const candidateMatches = candidateRules(evidence)
    .map((entry) => scoreRule(entry, evidence))
    .filter(Boolean)
    .sort((left, right) => right.consensusScore - left.consensusScore || right.score - left.score || left.entry.id.localeCompare(right.entry.id));

  if (!candidateMatches.length) return fallbackClassification(product, audience, attributes);

  // Evidence from a product title is more reliable than an incidental noun in
  // a supplier handle. For example, a "Watch" with "night light" in its
  // handle must remain a watch, and pants with "belt" in a handle must remain
  // pants. Tags only fill gaps when no direct product evidence exists.
  // A fallback such as "fashion" matching the word "wear" in a title must
  // never eclipse a specific product noun found in the title or handle. Keep
  // generic rules only when no specific rule has direct product evidence.
  const specificDirectCandidates = candidateMatches.filter((match) =>
    !match.entry.generic && match.directEvidenceRank > 0,
  );
  const directCandidatePool = specificDirectCandidates.length
    ? specificDirectCandidates
    : candidateMatches;
  // Some imports reduce a precise product title to a broad noun such as
  // "Pens". A taxonomy rule may opt into its explicit multi-word handle
  // phrase taking precedence, without allowing arbitrary handle noise to
  // eclipse a clear title noun such as "Watch".
  const preferredHandleCandidates = directCandidatePool.filter((match) =>
    match.entry.preferSpecificHandle === true &&
    match.fields.includes("handle") &&
    match.terms.some((term) =>
      (() => {
        const tokens = phraseTokens(term);
        const isSpecificSingleToken = match.entry.preferSpecificHandleSingleToken === true &&
          tokens.length === 1 && tokens[0].length >= 8;
        return (tokens.length >= 2 || isSpecificSingleToken) && includesPhrase(evidence.fields.handle || [], tokens);
      })(),
    ),
  );
  const evidenceCandidatePool = preferredHandleCandidates.length
    ? preferredHandleCandidates
    : directCandidatePool;
  const strongestDirectEvidenceRank = Math.max(
    ...evidenceCandidatePool.map((match) => match.directEvidenceRank),
  );
  const matches = strongestDirectEvidenceRank > 0
    ? evidenceCandidatePool.filter((match) => match.directEvidenceRank === strongestDirectEvidenceRank)
    : evidenceCandidatePool;

  const best = matches[0];
  const runnerUp = matches[1];
  const resolvedAudience = applyRuleAudienceOverride(best.entry, audience);
  const taxonomy = resolveAudienceTaxonomy(best.entry, resolvedAudience);
  const scoreGap = runnerUp ? best.consensusScore - runnerUp.consensusScore : Number.POSITIVE_INFINITY;
  const hasTitleOrHandle = best.titleOrHandle;
  const reviewReasons = [];
  const weakGenericMatch = best.entry.generic && (
    !best.titleOrHandle ||
    best.entry.familyId === "apparel" ||
    best.terms.length < 2
  );
  let confidence = 45 + Math.min(22, Math.floor(best.entry.priority / 4));
  if (best.titleOrHandle) confidence += 16;
  else if (best.primaryEvidence) confidence += 8;
  else confidence -= 16;
  if (best.terms.length >= 2) confidence += 5;
  if (best.directFields.length >= 2) confidence += 4;
  if (best.directPhraseCount) confidence += 4;
  if (best.entry.generic) confidence -= weakGenericMatch ? 18 : 4;
  if (!best.independentEvidence && best.terms.length < 2) {
    confidence -= 10;
    reviewReasons.push("single-evidence-lane");
  }
  const crossFamilyConflict = runnerUp && runnerUp.entry.familyId !== best.entry.familyId;
  const hasStrongDirectPhrase = best.directPhraseCount > 0 && best.directEvidenceRank >= 2;
  if (scoreGap < 8 && crossFamilyConflict) {
    confidence -= 12;
    reviewReasons.push(`ambiguous-with:${runnerUp.entry.id}`);
  }
  if (crossFamilyConflict && best.directFields.length <= 1 && !hasStrongDirectPhrase && scoreGap < 18) {
    confidence -= 10;
    reviewReasons.push(`weak-cross-family-consensus:${runnerUp.entry.id}`);
  }
  if (!hasTitleOrHandle) reviewReasons.push("no-title-or-handle-evidence");
  if (weakGenericMatch) reviewReasons.push("generic-fallback-rule");
  confidence = Math.max(20, Math.min(99, Math.round(confidence)));

  const classification = {
    version: CATALOG_TAXONOMY_VERSION,
    ruleId: best.entry.id,
    familyId: best.entry.familyId,
    familyLabel: FAMILY_LABELS[best.entry.familyId] || FAMILY_LABELS.other,
    departmentId: taxonomy.departmentId,
    departmentLabel: taxonomy.departmentLabel,
    categoryId: taxonomy.categoryId,
    categoryLabel: taxonomy.categoryLabel,
    subcategoryId: best.entry.subcategoryId,
    subcategoryLabel: best.entry.subcategoryLabel,
    canonicalType: best.entry.canonicalType,
    canonicalTypeId: toTypeId(best.entry.canonicalType),
    audience: resolvedAudience,
    attributes,
    relatedCategories: resolveRelatedCategories(best.entry, taxonomy),
    aliases: unique([best.entry.canonicalType, ...best.entry.aliases, ...best.terms]).slice(0, 24),
    negativeTerms: normalizeTerms(best.entry.excludes).slice(0, 16),
    collectionTargets: resolveCollectionTargets(best.entry, resolvedAudience),
    shopifyCategory: best.entry.shopifyCategory || null,
    confidence,
    reviewRequired: confidence < 72 || reviewReasons.length > 0,
    reviewReasons,
    evidence: {
      fields: best.fields,
      terms: best.terms,
      lanes: best.evidenceLanes,
      directFields: best.directFields,
      directPhraseCount: best.directPhraseCount,
      requiredGroupCount: best.requiredGroupCount,
      independentEvidence: best.independentEvidence,
    },
  };
  classification.seoEligible = best.entry.seoEligible !== false && !classification.reviewRequired;
  classification.proposedTags = classification.seoEligible ? buildTaxonomyTags(classification) : [];
  return classification;
}

export function classifyCatalogTaxonomyWithoutOverrides(product) {
  return classifyCatalogTaxonomy(product, { ignoreOverride: true });
}

export function getCatalogTaxonomyDefinitions() {
  return TAXONOMY_RULES.map((entry) => ({
    id: entry.id,
    familyId: entry.familyId,
    departmentId: entry.departmentId || entry.audienceCategory || "dynamic",
    categoryId: entry.categoryId || entry.audienceCategory || "dynamic",
    subcategoryId: entry.subcategoryId,
    canonicalType: entry.canonicalType,
    terms: entry.terms,
    requires: entry.requires,
    excludes: entry.excludes,
    primaryTerms: entry.primaryTerms,
    priority: entry.priority,
    aliases: entry.aliases,
    collectionTargets: entry.collectionTargets,
    relatedCategories: entry.relatedCategories,
    shopifyCategory: entry.shopifyCategory || null,
    generic: Boolean(entry.generic),
  }));
}

export function getCatalogDepartmentDefinitions() {
  return Object.entries(DEPARTMENTS).map(([id, label]) => ({ id, label }));
}
